            <div v-else class="resource-table-wrap"><table class="resource-table"><caption class="sr-only">{{currentCollection.name}}的资料列表</caption><thead><tr><th class="check-column"><input type="checkbox" aria-label="选择当前页全部资料" :checked="checked.length===resources.length&&resources.length>0" :indeterminate="checked.length>0&&checked.length<resources.length" @change="toggleAll" /></th><th>资料名称</th><th class="optional-column">正文</th><th class="status-column">检索状态</th><th class="optional-column date-column">更新于</th><th class="row-action-column"><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="item in resources" :key="item.resource_id" :class="{active:previewId===item.resource_id}"><td class="check-column"><input type="checkbox" :aria-label="'选择 '+item.title" :checked="checked.includes(item.resource_id)" @change="toggleChecked(item.resource_id)" /></td><td><button class="resource-title" :data-source-resource="item.resource_id" @click="openPreview(item.resource_id)"><span class="file-type-icon" :class="typeClass(item.kind)"><FileText :size="19" :stroke-width="1.5" /></span><span><strong>{{item.title}}</strong><small>{{typeName(item.kind)}}<template v-if="item.tags?.length"> · {{item.tags.join(' / ')}}</template><template v-else> · {{item.file_size?formatBytes(item.file_size):'手动整理'}}</template></small></span></button></td><td class="optional-column content-count">{{formatNumber(item.characters)}}<small>字</small></td><td class="status-column"><span class="index-status" :class="{indexed:item.indexed}"><span></span>{{item.indexed?'向量已就绪':'关键词可用'}}</span></td><td class="optional-column date-column" :title="fullDate(item.updated_at)">{{relativeDate(item.updated_at)}}</td><td><button class="icon-button" :aria-label="'预览 '+item.title" @click="openPreview(item.resource_id)"><ChevronRight :size="16" /></button></td></tr></tbody></table></div>
            <footer class="list-footer"><span>{{total}} 份资料<span v-if="checked.length"> · 已选择 {{checked.length}} 份</span></span><div v-if="total>pageSize" class="pagination-controls"><button class="icon-button" aria-label="上一页资料" :disabled="page===0" @click="page--"><ChevronLeft :size="15" /></button><span>{{page+1}} / {{Math.ceil(total/pageSize)}}</span><button class="icon-button" aria-label="下一页资料" :disabled="(page+1)*pageSize>=total" @click="page++"><ChevronRight :size="15" /></button></div><span v-else class="list-footnote">原文与取材依据，保留在一起。</span></footer>
          </div>
          <section v-show="activeTab==='search'" id="search-panel" role="tabpanel" aria-labelledby="search-tab" class="search-panel">
            <div class="search-intro"><h3>先找到依据，再组织答案。</h3><p>查看检索命中的原文，确认知识库是否能回答你的问题。</p></div>
            <form @submit.prevent="search" class="retrieval-form"><label class="sr-only" for="knowledge-query">检索问题</label><div class="retrieval-input"><Search :size="18" /><input id="knowledge-query" v-model="query" required maxlength="2000" placeholder="输入一个问题或关键词，例如：项目的验收范围是什么？" /><button class="button primary" :disabled="searching || !query.trim()"><LoaderCircle v-if="searching" :size="14" class="spin" />{{searching?'检索中…':'检索资料'}}<ArrowRight v-if="!searching" :size="14" /></button></div><div class="retrieval-options"><label>检索方式<select v-model="mode"><option value="keyword">关键词</option><option value="intelligent">智能检索</option><option value="semantic">语义检索</option><option value="file">文件级</option></select></label><label>返回结果<select v-model.number="topK"><option :value="5">5 条</option><option :value="10">10 条</option><option :value="20">20 条</option></select></label><label class="all-collections"><input v-model="searchAll" type="checkbox" />搜索全部知识库</label></div></form>
            <div class="answer-toolbar"><span v-if="!modelConfigured"><CircleHelp :size="14" />配置生成模型后，可基于检索资料问答。</span><span v-else class="muted">仅使用命中的资料组织回答，仍需人工核对。</span><button class="button small" :disabled="searching||answering||!modelConfigured||!query.trim()" @click="answerQuestion"><LoaderCircle v-if="answering" :size="14" class="spin" /><Sparkles v-else :size="14" />{{answering?'正在组织答案…':'基于资料回答'}}</button></div>
            <article v-if="answer" class="answer-result"><header><Sparkles :size="17" /><h3>基于资料的回答</h3><button class="icon-button" aria-label="复制回答" @click="copyText(answer)"><Copy :size="14" /></button></header><p>{{answer}}</p></article>
            <div v-if="searched" class="search-results-heading"><h3>命中 {{results.length}} 条资料</h3><small>点击来源可查看原文</small></div><div v-if="searched&&!results.length" class="empty-resources compact"><Search :size="27" :stroke-width="1.3" /><h3>暂时没有找到相关内容</h3><p>尝试更具体的关键词，或为知识库补充资料。</p></div>
            <article v-for="(result,i) in results" :key="i" class="search-result"><header><span class="source-number">{{i+1}}</span><button @click="result.resource_id&&openPreview(result.resource_id)">{{result.title}}<ArrowUpRight :size="13" /></button><small v-if="typeof result.score==='number'">匹配分 {{result.score.toFixed(2)}}</small></header><p><template v-for="(part,j) in highlighted(result.content)" :key="j"><mark v-if="part.match">{{part.text}}</mark><span v-else>{{part.text}}</span></template></p><footer><span>{{collectionNameFor(result.collection_id)}}</span><span v-if="result.version">版本 {{result.version}}</span><button v-if="result.resource_id" class="text-button" @click="openPreview(result.resource_id)">查看来源<ChevronRight :size="12" /></button></footer></article>
            <div v-if="!searched&&!searching" class="search-hint"><BookOpen :size="26" :stroke-width="1.3" /><p>从一个具体的问题开始。<br /><span>检索结果会显示原文、来源和匹配分。</span></p></div>
          </section>
        </template>
      </section>
      <aside v-if="previewId" class="preview-panel" aria-label="资料预览">
        <header class="preview-top"><span><BookOpen :size="15" />资料预览</span><button ref="previewCloseButton" class="icon-button" aria-label="关闭资料预览" @click="closePreview"><PanelRightClose :size="17" /></button></header>
        <div v-if="detailLoading" class="preview-loading"><LoaderCircle :size="20" class="spin" /><p>正在读取原文…</p></div>
        <template v-else-if="detail"><div class="preview-document-heading"><span class="document-kind">{{typeName(detail.kind)}}</span><h2>{{detail.title}}</h2><p>{{collectionNameFor(detail.collection_id)}}</p><div class="preview-facts"><span>{{formatNumber(detail.characters)}} 字</span><span>版本 {{detail.version}}</span><span>{{detail.indexed?'已建立向量索引':'关键词可用'}}</span></div></div>
          <div class="preview-actions"><button class="button small" @click="copyText(detail.content)"><Copy :size="13" />复制正文</button><button class="button small" @click="downloadOriginal"><Download :size="13" />{{detail.has_original?'下载原文件':'导出文本'}}</button></div>
          <div class="preview-tabs"><button :class="{active:previewTab==='content'}" @click="previewTab='content'">原文</button><button :class="{active:previewTab==='segments'}" @click="previewTab='segments'">内容分段 <small>{{detail.segments.length}}</small></button><button :class="{active:previewTab==='info'}" @click="previewTab='info'">资料信息</button></div>
          <div v-if="previewTab==='content'" class="preview-prose">{{detail.content}}</div>
          <div v-else-if="previewTab==='segments'" class="preview-segments"><p class="segment-explanation">用于阅读的内容分段，不代表已完成向量索引。</p><article v-for="(segment,i) in detail.segments" :key="i"><header><span>片段 {{i+1}}</span><small>{{segment.start}}–{{segment.end}} 字符</small></header><p>{{segment.content}}</p></article></div>
          <div v-else class="preview-information"><form @submit.prevent="saveMetadata"><label class="field-label">资料名称<input v-model="metadataTitle" required maxlength="255" class="field-input" /></label><label class="field-label">标签<input v-model="metadataTags" class="field-input" maxlength="800" placeholder="用逗号分隔" /></label><button class="button small" :disabled="metadataSaving">{{metadataSaving?'保存中…':'保存信息'}}</button></form><dl><dt>来源文件</dt><dd>{{detail.file_name||'粘贴文本'}}</dd><dt>更新时间</dt><dd>{{fullDate(detail.updated_at)}}</dd><dt>检索状态</dt><dd>{{detail.indexed?'向量索引已建立':'已保存正文，可使用关键词检索'}}</dd></dl><button class="button small" :disabled="reindexing" @click="reindexResource"><RefreshCw :size="13" :class="{spin:reindexing}" />{{reindexing?'正在建立索引…':'重建向量索引'}}</button><div class="delete-zone"><template v-if="confirmDelete"><p>将从知识库和检索中移除这份资料，已生成的文档不受影响。</p><button class="button danger small" :disabled="deleting" @click="removeResource">确认移除资料</button><button class="button ghost small" @click="confirmDelete=false">取消</button></template><button v-else class="text-button delete-action" @click="confirmDelete=true"><Trash2 :size="13" />移除资料</button></div></div>
          <footer class="preview-bottom"><button class="text-button" @click="writeWithCollection"><PenLine :size="14" />使用这些资料写作<ArrowUpRight :size="13" /></button></footer>
        </template>
      </aside>
    </div>
  </section>
</template>
<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { AlertCircle, ArrowRight, ArrowUpRight, BookOpen, CheckCircle2, ChevronLeft, ChevronRight, CircleHelp, Copy, Download, FileText, FileUp, Folder, FolderOpen, Library, LoaderCircle, PanelRightClose, Pencil, PenLine, Plus, RefreshCw, Search, Sparkles, Trash2, Upload, X } from '@lucide/vue';
import { api, downloadFile, handleError } from '../api/client';
import '../styles/knowledge.css';
const router=useRouter();
const overview=ref({collections:[],document_count:0,characters:0,indexed_count:0}),collections=computed(()=>overview.value.collections),selected=ref(''),currentCollection=computed(()=>collections.value.find(c=>c.id===selected.value));
const overviewLoading=ref(true),overviewFailed=ref(false),notice=ref(''),noticeType=ref('info'),activeTab=ref('documents'),modelConfigured=ref(false);
const collectionForm=ref(false),collectionName=ref(''),collectionDescription=ref(''),editingCollection=ref(''),collectionSaving=ref(false),collectionNameInput=ref(null);
const resources=ref([]),total=ref(0),listQuery=ref(''),kind=ref('all'),page=ref(0),pageSize=20,listLoading=ref(false),checked=ref([]),confirmBulk=ref(false),deleting=ref(false);
const showImport=ref(false),importMethod=ref('file'),fileInput=ref(null),uploading=ref(false),dragging=ref(false),uploadQueue=ref([]),textTitle=ref(''),textContent=ref(''),textTags=ref(''),textSaving=ref(false);
const previewCloseButton=ref(null),previewId=ref(''),detail=ref(null),detailLoading=ref(false),previewTab=ref('content'),metadataTitle=ref(''),metadataTags=ref(''),metadataSaving=ref(false),confirmDelete=ref(false),reindexing=ref(false);
const query=ref(''),mode=ref('keyword'),topK=ref(5),searchAll=ref(false),searching=ref(false),searched=ref(false),results=ref([]),answer=ref(''),answering=ref(false);
let listSequence=0,previewSequence=0,filterTimer,lastPreviewTrigger,lastPreviewResource;
function notify(message,type='info'){notice.value=message;noticeType.value=type;}
function formatNumber(value){return Number(value||0).toLocaleString('zh-CN');}
function formatBytes(bytes){return bytes<1024?bytes+' B':bytes<1048576?(bytes/1024).toFixed(1)+' KB':(bytes/1048576).toFixed(1)+' MB';}
function typeName(kind){return ({pdf:'PDF',docx:'Word',md:'Markdown',txt:'文本',text:'文本',csv:'CSV',json:'JSON'})[kind]||'文档';}
function typeClass(kind){return kind==='pdf'?'pdf':kind==='docx'?'word':'text';}
function parsedDate(value){return value?new Date(/(?:Z|[+-]\d\d:\d\d)$/.test(value)?value:value+'Z'):null;}
function fullDate(value){const date=parsedDate(value);return date&&!Number.isNaN(date.getTime())?date.toLocaleString('zh-CN',{hour12:false}):'—';}
function relativeDate(value){const date=parsedDate(value);if(!date||Number.isNaN(date.getTime()))return '—';const minutes=Math.max(0,Math.floor((Date.now()-date.getTime())/60000));return minutes<1?'刚刚':minutes<60?minutes+' 分钟前':minutes<1440?Math.floor(minutes/60)+' 小时前':date.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});}
function collectionNameFor(id){return collections.value.find(c=>c.id===id)?.name||'知识库资料';}
async function loadOverview(preferred){overviewLoading.value=true;overviewFailed.value=false;try{overview.value=(await api.get('/api/v1/knowledge/overview')).data;if(preferred)selected.value=preferred;else if(!collections.value.some(c=>c.id===selected.value))selected.value=collections.value[0]?.id||'';}catch(error){overviewFailed.value=true;notify(handleError(error),'error');}finally{overviewLoading.value=false;}}
async function loadResources(){if(!selected.value)return;const sequence=++listSequence;listLoading.value=true;try{const r=await api.get('/api/v1/knowledge/resources',{params:{collection_id:selected.value,query:listQuery.value,kind:kind.value,page:page.value,size:pageSize}});if(sequence!==listSequence)return;resources.value=r.data.items;total.value=r.data.total;checked.value=checked.value.filter(id=>resources.value.some(item=>item.resource_id===id));if(!resources.value.length&&page.value>0)page.value=Math.max(0,Math.ceil(total.value/pageSize)-1);}catch(error){if(sequence===listSequence)notify(handleError(error),'error');}finally{if(sequence===listSequence)listLoading.value=false;}}
async function refreshAll(){await Promise.all([loadOverview(),loadResources()]);}
function changeTab(tab){activeTab.value=tab;nextTick(()=>document.getElementById(tab==='search'?'search-tab':'documents-tab')?.focus());}
function startCollection(collection){collectionForm.value=true;editingCollection.value=collection?.id||'';collectionName.value=collection?.name||'';collectionDescription.value=collection?.description||'';nextTick(()=>collectionNameInput.value?.focus());}
async function saveCollection(){if(!collectionName.value.trim())return;collectionSaving.value=true;try{const body={name:collectionName.value.trim(),description:collectionDescription.value.trim()};const r=editingCollection.value?await api.patch('/api/v1/knowledge/collections/'+editingCollection.value,body):await api.post('/api/v1/knowledge/collections',body);const id=editingCollection.value||r.data.result.id;await loadOverview(id);collectionForm.value=false;notify(editingCollection.value?'知识库信息已更新。':'知识库已创建，可以开始导入资料。');}catch(error){notify(handleError(error),'error');}finally{collectionSaving.value=false;}}
function tagsFrom(value){return [...new Set(value.split(/[,，]/).map(s=>s.trim()).filter(Boolean))].slice(0,20);}
async function saveText(){if(!selected.value)return;textSaving.value=true;try{await api.post('/api/v1/knowledge/text',{collection_id:selected.value,title:textTitle.value,content:textContent.value,tags:tagsFrom(textTags.value)},{timeout:180000});textTitle.value='';textContent.value='';textTags.value='';await refreshAll();notify('资料已保存，现在可以用关键词检索。');}catch(error){notify(handleError(error),'error');}finally{textSaving.value=false;}}
function filesChosen(event){importFiles(Array.from(event.target.files||[]));event.target.value='';}
function filesDropped(event){dragging.value=false;if(!uploading.value)importFiles(Array.from(event.dataTransfer.files||[]));}
async function importFiles(files){if(!files.length||uploading.value||!selected.value)return;if(files.length>10){notify('每次最多导入 10 个文件，请分批导入。','error');return;}const collectionId=selected.value;uploading.value=true;uploadQueue.value=files.map(file=>({name:file.name,state:'queued',message:'等待导入'}));let imported=0;for(let i=0;i<files.length;i++){const entry=uploadQueue.value[i];entry.state='loading';entry.message='正在解析';try{const form=new FormData();form.append('collection_id',collectionId);form.append('file',files[i]);const r=await api.post('/api/v1/knowledge/import',form,{timeout:180000});entry.state='done';entry.message=r.data.duplicate?'已存在，跳过重复导入':r.data.vector_indexed?'已导入并建立索引':'已导入 · 关键词可用';imported++;}catch(error){entry.state='error';entry.message=handleError(error);}}uploading.value=false;await refreshAll();notify(`已完成 ${imported}/${files.length} 个文件的导入。`,imported===files.length?'info':'error');}
function toggleChecked(id){checked.value=checked.value.includes(id)?checked.value.filter(v=>v!==id):[...checked.value,id];confirmBulk.value=false;}
function toggleAll(){checked.value=checked.value.length===resources.value.length?[]:resources.value.map(r=>r.resource_id);confirmBulk.value=false;}
async function openPreview(id,{refresh=false}={}){if(!refresh){lastPreviewTrigger=document.activeElement;lastPreviewResource=id;}const sequence=++previewSequence;previewId.value=id;detail.value=null;detailLoading.value=true;previewTab.value='content';confirmDelete.value=false;await nextTick();if(!refresh&&sequence===previewSequence)previewCloseButton.value?.focus();try{const r=await api.get('/api/v1/knowledge/resources/'+id);if(sequence!==previewSequence)return;detail.value=r.data;metadataTitle.value=r.data.title;metadataTags.value=(r.data.tags||[]).join('，');}catch(error){if(sequence===previewSequence){notify(handleError(error),'error');closePreview();}}finally{if(sequence===previewSequence)detailLoading.value=false;}}
function closePreview(){previewSequence++;previewId.value='';detail.value=null;confirmDelete.value=false;nextTick(()=>{if(lastPreviewTrigger?.isConnected&&lastPreviewTrigger.offsetParent!==null)lastPreviewTrigger.focus();else{const replacement=[...document.querySelectorAll('[data-source-resource]')].find(element=>element.dataset.sourceResource===lastPreviewResource&&element.offsetParent!==null);if(replacement)replacement.focus();else document.getElementById(activeTab.value==='search'?'search-tab':'documents-tab')?.focus();}});}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('已复制。');}catch{notify('浏览器未允许复制，请在原文中选择文字后复制。','error');}}
function downloadOriginal(){if(detail.value.has_original){downloadFile('/api/v1/knowledge/resources/'+previewId.value+'/download',detail.value.file_name||detail.value.title);return;}const url=URL.createObjectURL(new Blob([detail.value.content],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=detail.value.title+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function saveMetadata(){metadataSaving.value=true;try{await api.patch('/api/v1/knowledge/resources/'+previewId.value,{title:metadataTitle.value,tags:tagsFrom(metadataTags.value)});detail.value.title=metadataTitle.value;detail.value.tags=tagsFrom(metadataTags.value);await loadResources();notify('资料信息已更新。');}catch(error){notify(handleError(error),'error');}finally{metadataSaving.value=false;}}
async function reindexResource(){reindexing.value=true;try{await api.post('/api/v1/knowledge/resources/'+previewId.value+'/reindex',{}, {timeout:180000});await openPreview(previewId.value,{refresh:true});await refreshAll();notify('向量索引已更新。');}catch(error){notify(handleError(error),'error');}finally{reindexing.value=false;}}
async function removeResource(){deleting.value=true;try{const removedId=previewId.value;const r=await api.delete('/api/v1/knowledge/resources/'+removedId);results.value=results.value.filter(item=>item.resource_id!==removedId);answer.value='';closePreview();await refreshAll();notify(r.data.cleanup_pending?'资料已移除，部分索引清理尚未完成。':'资料已移除。');}catch(error){notify(handleError(error),'error');}finally{deleting.value=false;}}
async function removeSelected(){deleting.value=true;let removed=0;const failures=[];for(const id of [...checked.value]){try{await api.delete('/api/v1/knowledge/resources/'+id);removed++;results.value=results.value.filter(item=>item.resource_id!==id);answer.value='';if(previewId.value===id)closePreview();}catch{failures.push(id);}}checked.value=failures;confirmBulk.value=false;await refreshAll();notify(failures.length?`已移除 ${removed} 份，${failures.length} 份未完成，请重试。`:`已移除 ${removed} 份资料。`,failures.length?'error':'info');deleting.value=false;}
function retrievalPayload(){return {query:query.value,collection_ids:searchAll.value?collections.value.map(c=>c.id):[selected.value],mode:mode.value,top_k:topK.value};}
async function search(){searching.value=true;answer.value='';try{const r=await api.post('/api/v1/knowledge/search',retrievalPayload(),{timeout:180000});results.value=r.data.sources;searched.value=true;}catch(error){notify(handleError(error),'error');}finally{searching.value=false;}}
async function answerQuestion(){answering.value=true;answer.value='';try{const r=await api.post('/api/v1/knowledge/answer',retrievalPayload(),{timeout:180000});answer.value=r.data.answer;results.value=r.data.sources;searched.value=true;}catch(error){notify(handleError(error),'error');}finally{answering.value=false;}}
function highlighted(text){const snippet=(text||'').slice(0,650);const tokens=query.value.trim().split(/\s+/).filter(t=>t.length>1);if(!tokens.length)return[{text:snippet,match:false}];const escaped=tokens.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const regex=new RegExp('('+escaped.join('|')+')','gi');return snippet.split(regex).map((part,i)=>({text:part,match:i%2===1})).filter(part=>part.text);}
function writeWithCollection(){router.push({path:'/writing',query:{collection:detail.value?.collection_id||selected.value}});}
function escapePreview(event){if(event.key==='Escape'&&previewId.value)closePreview();}
watch(selected,()=>{page.value=0;checked.value=[];listQuery.value='';results.value=[];answer.value='';searched.value=false;closePreview();loadResources();});
watch(kind,()=>{page.value=0;loadResources();});watch(page,loadResources);watch(listQuery,()=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>{page.value=0;loadResources();},250);});
onMounted(async()=>{document.addEventListener('keydown',escapePreview);await loadOverview();try{modelConfigured.value=(await api.get('/api/v1/status')).data.model_configured;}catch{/* Overview shows authentication errors. */}});
onUnmounted(()=>{clearTimeout(filterTimer);document.removeEventListener('keydown',escapePreview);listSequence++;previewSequence++;});
</script>
